import {INGREDIENTS,KEYS,SAMPLE_ORDERS,SEED_RECIPES,recipeMacros,labelMacros,scaleMacros,totals,parseLabel,localDay,positive} from './core.js';
import {MEAL_DISHES,OTHER_LABELS,estimatePhotoMeal,diaryScenarioRange,rankMealMatches} from './meal-data.js';
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const escape=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const fmt=(n,d=0)=>Number(n).toLocaleString('en-IN',{maximumFractionDigits:d});
const uid=()=>crypto.randomUUID();
const STORAGE='thali-demo-v1';
let state,storageAvailable=true;
function fresh(){
 const breakfast=recipeMacros(SEED_RECIPES[2].rows,250,250).portion;
 return {version:1,goals:{kcal:2000,protein:90,carbs:250,fat:65},recipes:structuredClone(SEED_RECIPES),entries:[
  {id:'seed-breakfast',name:'Banana overnight oats',source:'home',provenance:'Recipe estimate · illustrative references',meal:'Breakfast',day:localDay(),portion:'250 g',macros:breakfast},
  {id:'seed-lunch',name:'Paneer tikka bowl',source:'order',provenance:'Fictional sample order · illustrative values',meal:'Lunch',day:localDay(),portion:'1 portion',macros:{...SAMPLE_ORDERS[0].macros}},
  {id:'seed-snack',name:'Roasted chana',source:'snack',provenance:'Illustrative sample label · user reviewed',meal:'Snack',day:localDay(),portion:'30 g',macros:{kcal:114,protein:6,carbs:18,fat:1.8}},
 ]};
}
try{state=JSON.parse(localStorage.getItem(STORAGE));if(!state||state.version!==1||!Array.isArray(state.entries)||!Array.isArray(state.recipes)||!state.goals)state=fresh();}catch{state=fresh();storageAvailable=false;}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{storageAvailable=false;toast('Browser storage unavailable. Keep this tab open or export your diary.');}}
let activeTab='home',communityFilter='all',selectedDay=localDay(),photoURL='',scanWorker=null,toastTimer;
let mealPhotoURL='',mealRows=[],mealResults=null,mealStatus='',mealWorker=null,mealBusy=false,mealRequest=0,mealUsedAI=false;
let mealDraft={name:'My meal photo',meal:'Lunch',oil:0};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function macrosHTML(m){return `<div class="macro-stats">${KEYS.map(k=>`<div><b>${fmt(m[k],k==='kcal'?0:1)}${k==='kcal'?'':'g'}</b><small>${({kcal:'Calories · kcal',protein:'Protein',carbs:'Carbs',fat:'Fat'})[k]}</small></div>`).join('')}</div>`;}
const plate=()=>'<div class="plate" aria-hidden="true"><div class="food-rice"></div><div class="food-dal"></div><div class="food-leaf"></div><div class="food-tomato"></div></div>';
function heading(eyebrow,title,copy,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${copy}</p></div>${extra}</div>`;}
function entryHTML(e){return `<div class="diary-entry"><div class="food-thumb ${e.source}">${icon(e.source==='photo'?'camera':e.source==='home'?'home':e.source==='order'?'bag':'scan')}</div><div class="entry-text"><div class="entry-meta">${escape(e.meal)} &nbsp;·&nbsp; ${e.source==='photo'?'Meal photo estimate':e.source==='home'?'Home cooked':e.source==='order'?'Zomato sample':'Packaged snack'}</div><h3>${escape(e.name)}</h3><p>${escape(e.portion)} &nbsp;·&nbsp; P ${fmt(e.macros.protein,1)}g &nbsp; C ${fmt(e.macros.carbs,1)}g &nbsp; F ${fmt(e.macros.fat,1)}g</p><div class="diary-source">${escape(e.provenance)}${e.macroRange?' · '+fmt(e.macroRange.low.kcal)+'–'+fmt(e.macroRange.high.kcal)+' kcal scenario range':''}</div></div><div class="entry-kcal">${e.macroRange?'≈':''}${fmt(e.macros.kcal)}<br><small>kcal</small></div><button class="delete-btn" data-action="delete-entry" data-id="${escape(e.id)}" aria-label="Remove ${escape(e.name)}">×</button></div>`;}
function renderToday(){
 const entries=state.entries.filter(e=>e.day===selectedDay),t=totals(entries),g=state.goals,range=diaryScenarioRange(entries),hasPhoto=entries.some(e=>e.macroRange);
 const date=new Date(selectedDay+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
 return `${heading('A LITTLE MORE AWARE, EVERY DAY','Your whole day.<br>One nourishing picture.','Home cooked, ordered in, or a snack on the go. It all belongs here.',`<span class="date-chip">${date}</span>`)}
 <div class="layout"><div class="left-col"><section class="hero"><div class="hero-copy"><div class="eyebrow">FROM YOUR KITCHEN TO YOUR DOORSTEP</div><h2>Different meals.<br>One simple diary.</h2><p>Understand what goes into your day,<br>one plate at a time.</p><a href="#add" class="btn lime">${icon('plus')}Log a meal</a></div>${plate()}</section>
 <div class="section-head"><h2>What’s on your plate?</h2><span>Four ways to add food</span></div><button class="meal-quick" data-action="add-tab" data-tab="photo"><span class="source-icon">${icon('camera')}</span><span><b>Snap your meal</b><small>AI dish suggestions · approximate nutrition · you review</small></span><span class="pill">NEW · AI</span>${icon('arrow')}</button><div class="source-grid">
 <button class="source-card" data-action="add-tab" data-tab="home"><span class="source-icon">${icon('home')}</span><b>Home cooked</b><small>Ingredients to insights</small>${icon('arrow').replace('<svg','<svg class="source-arrow"')}</button>
 <button class="source-card" data-action="add-tab" data-tab="orders"><span class="source-icon zomato">${icon('bag')}</span><b>Zomato orders</b><small>Try a sample order</small>${icon('arrow').replace('<svg','<svg class="source-arrow"')}</button>
 <button class="source-card" data-action="add-tab" data-tab="label"><span class="source-icon snack">${icon('scan')}</span><b>Packaged snacks</b><small>Scan. Review. Log.</small>${icon('arrow').replace('<svg','<svg class="source-arrow"')}</button></div>
 <div class="section-head"><h2>${selectedDay===localDay()?'Today’s':'Your'} food diary <span>(${entries.length})</span></h2><label class="history-date">Date <input id="diary-date" type="date" value="${selectedDay}" max="${localDay()}" aria-label="Diary date"></label></div><section class="card diary" aria-label="Food diary">${entries.length?entries.map(entryHTML).join(''):'<div class="empty">A fresh page for your day.<p>Add your first meal to start your diary.</p></div>'}</section>
 </div><aside class="right-col"><section class="card summary"><div class="card-heading"><h3>Your daily snapshot</h3><button class="text-btn" data-action="goals">Edit goals</button></div><div class="ring-wrap"><div class="ring" style="--progress:${Math.min(100,t.kcal/g.kcal*100)}%"><div class="ring-inner"><b>${hasPhoto?'≈':''}${fmt(t.kcal)}</b><small>of ${fmt(g.kcal)} kcal</small></div></div></div>${['protein','carbs','fat'].map(k=>`<div class="macro-row"><span class="macro-label"><span class="macro-dot ${k}"></span>${k[0].toUpperCase()+k.slice(1)}</span><b>${hasPhoto?'≈ ':''}${fmt(t[k],1)} <span class="small-copy">/ ${fmt(g[k])} g</span></b></div><div class="bar ${k}"><span style="width:${Math.min(100,t[k]/g[k]*100)}%"></span></div>`).join('')}<div class="summary-note">${hasPhoto?'Photo uncertainty included: '+fmt(range.low.kcal)+'–'+fmt(range.high.kcal)+' kcal<br>':''}Example goals · edit to your own preferences<br>Totals are estimates based on your entries.</div></section>
 <div><section class="inspiration"><div class="eyebrow">GOOD FOOD IS BETTER SHARED</div><h3>Someone’s everyday dish.<br>Your next favourite.</h3><p>Discover recipes with ingredients, portions and transparent macro estimates.</p><a class="text-btn" href="#community">Explore the community ${icon('arrow')}</a></section><p class="quiet-note">Sample recipes and orders are included to help you explore. Your diary and contributions stay in this browser.</p></div></aside></div>`;
}
function ingredientRow(row={id:'dal',grams:50},index=0){return `<div class="ingredient-row"><select aria-label="Ingredient ${index+1}" class="ingredient-id">${INGREDIENTS.map(i=>`<option value="${i.id}" ${i.id===row.id?'selected':''}>${i.name}</option>`).join('')}</select><input class="ingredient-grams" aria-label="Ingredient ${index+1} grams" type="number" min="0.1" max="100000" step="any" value="${row.grams}"><button type="button" class="remove-ingredient" data-action="remove-ingredient" aria-label="Remove ingredient ${index+1}">×</button></div>`;}
const mealSelect=(selected='Lunch')=>`<label class="field"><span>Meal</span><select name="meal">${['Breakfast','Lunch','Dinner','Snack'].map(m=>`<option ${m===selected?'selected':''}>${m}</option>`).join('')}</select></label>`;
function homeForm(){return `<section class="card form-card"><div class="form-intro"><div><h2>Made in your kitchen</h2><p>Build a recipe, weigh the cooked batch, and choose your portion.</p></div><span class="pill">RECIPE ESTIMATE</span></div>
 <form id="recipe-form"><div class="row"><label class="field"><span>Recipe name</span><input name="name" required maxlength="80" placeholder="e.g. My moong dal chilla" value="My moong dal chilla"></label>${mealSelect()}</div>
 <div class="row"><span class="label">Ingredients · raw quantities</span><span class="label" style="flex:0 0 127px">Weight in grams</span></div><div id="ingredients">${[{id:'dal',grams:70},{id:'onion',grams:30},{id:'tomato',grams:40},{id:'oil',grams:5}].map(ingredientRow).join('')}</div>
 <button class="text-btn" data-action="add-ingredient" type="button">+ Add ingredient</button><p class="field-hint">Include oil, ghee and other additions. Reference values are illustrative per 100 g raw ingredient.</p>
 <div class="row"><label class="field"><span>Final cooked recipe weight · g</span><input name="yield" type="number" min="1" max="100000" step="any" required value="230"></label><label class="field"><span>Your portion · g</span><input name="portion" type="number" min="1" max="100000" step="any" required value="230"></label></div>
 <div id="recipe-result" class="recipe-results"></div><label class="field"><span>Preparation note · optional, shown with shared recipes</span><textarea name="description" rows="2" maxlength="350" placeholder="Soak and blend the dal, add vegetables, and cook with the measured oil."></textarea></label>
 <p class="notice">Cooking changes water content and can change nutrient retention. This ingredient calculation is an estimate; the demo does not model nutrient loss.</p>
 <div class="action-row"><button class="btn" type="submit">${icon('plus')}Log my portion</button><button class="btn outline" type="button" data-action="publish-recipe">Share recipe in demo feed</button></div><p class="error" id="recipe-error" role="alert"></p></form></section>`;}
function ordersForm(){return `<section class="card form-card"><div class="form-intro"><div><h2>Your orders, in the picture</h2><p>Confirm how much you ate before adding a meal.</p></div><span class="pill orange">SAMPLE DATA</span></div><p class="notice">These restaurants, orders and nutrition values are fictional examples. No Zomato account is connected. A live integration would require approved access and nutrition data.</p>${SAMPLE_ORDERS.map(o=>`<div class="order-card"><div class="food-thumb order">${icon('bag')}</div><div class="order-details"><h3>${o.name}</h3><p>${o.restaurant} · ${o.time}</p><div class="order-meta">${fmt(o.macros.kcal)} kcal &nbsp;·&nbsp; P ${o.macros.protein}g &nbsp; C ${o.macros.carbs}g &nbsp; F ${o.macros.fat}g per portion</div></div><div class="order-controls"><label class="small-copy" for="portions-${o.id}">Portions eaten</label><input id="portions-${o.id}" type="number" min="0.1" max="20" step="0.1" value="1" aria-label="Portions of ${o.name}"><button class="btn small" data-action="log-order" data-id="${o.id}">+ Log</button></div></div>`).join('')}<p class="small-copy">Adding an order does not mean you ate it. Every log is an explicit confirmation.</p></section>`;}
function labelForm(){return `<section class="card form-card"><div class="form-intro"><div><h2>A little label clarity</h2><p>Read a clear photo, then review every value and the serving basis.</p></div><span class="pill">REVIEW REQUIRED</span></div>
 <div class="upload">${icon('scan')}<p>Photograph the nutrition information panel</p><small>Clear English text · one column works best · JPG, PNG or WebP · up to 10 MB</small><input id="label-file" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Upload nutrition label photo"><img id="label-preview" alt="Your selected nutrition label"><div class="scan-controls"><button class="btn small" data-action="scan">Read photo</button><button class="btn outline small" data-action="sample-label">Try a sample label</button></div><div class="status-line" id="scan-status" role="status"></div></div>
 <details><summary class="small-copy">Paste or correct label text instead</summary><label class="field" style="margin-top:12px"><span>Label text</span><textarea id="label-text" rows="6" placeholder="Per 100 g&#10;Energy 380 kcal&#10;Protein 20 g&#10;Carbohydrate 60 g&#10;Total fat 6 g"></textarea></label><button class="btn outline small" data-action="parse-label">Extract from text</button></details>
 <form id="label-form" style="margin-top:20px"><div class="row"><label class="field"><span>Snack or product name</span><input name="name" required maxlength="80" placeholder="e.g. Roasted chana"></label>${mealSelect()}</div>
 <div class="row"><label class="field"><span>These values are listed</span><select id="label-basis" name="basis" required><option value="">Confirm label basis</option><option value="100g">Per 100 g</option><option value="serving">Per serving</option></select></label><label class="field"><span>Label serving weight · g</span><input id="label-serving" name="basisGrams" type="number" min="0.1" step="any" placeholder="Required if per serving"></label></div>
 <div class="review-grid">${KEYS.map(k=>`<label class="field"><span>${({kcal:'Energy · kcal',protein:'Protein · g',carbs:'Carbs · g',fat:'Total fat · g'})[k]}</span><input id="label-${k}" name="${k}" type="number" min="0" step="any" required placeholder="Review value"></label>`).join('')}</div>
 <label class="field"><span>Amount you ate · g</span><input name="consumed" type="number" min="0.1" step="any" value="30" required></label><div id="label-result" class="recipe-results"><p class="small-copy">Your portion estimate appears after all values and the label basis are entered.</p></div>
 <p class="notice">OCR can mix up decimals or columns. Use kcal, not kJ. Confirm the per 100 g or per serving column yourself. Missing values must be entered before logging.</p><label class="small-copy" style="display:flex;align-items:flex-start;gap:9px"><input name="confirmed" type="checkbox" required style="width:15px;margin-top:2px">I checked the four values, units, label basis and amount eaten against the label.</label><div class="action-row"><button class="btn" type="submit">${icon('check')}Confirm and log snack</button></div><p class="error" id="label-error" role="alert"></p></form><p class="quiet-note">Photo recognition runs in your browser. OCR code and the English language model download on first use; your image is not uploaded. If the download fails, paste the text or enter the fields manually.</p></section>`;}
function mealRowHTML(row,index){return `<div class="ingredient-row meal-component"><select class="meal-dish" aria-label="Meal component ${index+1}">${MEAL_DISHES.map(d=>`<option value="${d.id}" ${row.id===d.id?'selected':''}>${d.name}</option>`).join('')}</select><input class="meal-grams" type="number" min="1" max="5000" step="any" value="${row.grams}" aria-label="Meal component ${index+1} grams"><button class="remove-ingredient" type="button" data-action="remove-meal-component" data-index="${index}" aria-label="Remove meal component ${index+1}">×</button><small class="component-hint">${escape(MEAL_DISHES.find(d=>d.id===row.id)?.portion||'')} · rough guide only</small></div>`;}
function mealForm(){return `<section class="card form-card"><div class="form-intro"><div><h2>A photo. A starting point.</h2><p>AI suggests likely dishes. You confirm what’s there and how much you ate.</p></div><span class="pill">ON DEVICE AI</span></div><div class="meal-steps"><span><b>1</b>Snap</span><span><b>2</b>Review</span><span><b>3</b>Estimate</span></div>
 <div class="upload meal-upload">${icon('camera')}<p>Take a photo or choose a meal image</p><small>JPG, PNG or WebP · up to 10 MB · include the whole plate</small><input id="meal-photo-file" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" aria-label="Choose meal photo"><img id="meal-photo-preview" ${mealPhotoURL?'src="'+escape(mealPhotoURL)+'"':''} alt="Meal photo to review">${mealPhotoURL.includes('sample-meal.jpg')?'<p class="photo-credit">Sample photo by <a href="https://commons.wikimedia.org/wiki/File:Idli_Sambar-Noida-UP-SP004.jpg" target="_blank" rel="noopener">Sutapa Pal</a> · resized preview · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY SA 4.0</a></p>':''}<div class="scan-controls"><button class="btn small" data-action="suggest-meal" ${mealBusy?'disabled':''}>${icon('camera')}Suggest dishes with AI</button><button class="btn outline small" data-action="sample-meal" ${mealBusy?'disabled':''}>Try a sample photo</button></div><div id="meal-ai-status" class="status-line" role="status">${escape(mealStatus||'First AI scan downloads about 155 MB of model weights plus the runtime. Your photo stays in the browser.')}</div>${mealBusy?'<button class="text-btn" data-action="cancel-meal">Stop scan</button>':''}</div>
 <div id="meal-matches"></div><form id="meal-form"><div class="form-intro"><div><h3>Review your plate</h3><p>Add each dish and edit the weight. AI does not measure portions.</p></div></div><div class="row"><label class="field"><span>Meal name</span><input name="name" required maxlength="80" value="${escape(mealDraft.name)}"></label>${mealSelect(mealDraft.meal)}</div><div class="row"><span class="label">Dishes on your plate</span><span class="label" style="flex:0 0 127px">Cooked weight · g</span></div><div id="meal-components">${mealRows.map(mealRowHTML).join('')}</div><button type="button" class="text-btn" data-action="add-meal-component">+ Add a dish manually</button><p class="field-hint">20 dish types supported. For another dish, use Home cooked and enter its ingredients.</p><label class="field"><span>Extra oil or ghee beyond the usual recipe · teaspoons</span><input name="oil" type="number" min="0" max="20" step="0.5" value="${escape(mealDraft.oil)}"></label><p class="small-copy">References already assume typical preparation. Add extra oil only if you know more was used. A photo cannot reveal hidden oil or fillings.</p><div id="meal-estimate" class="recipe-results"></div><details class="range-details"><summary>What does this range mean?</summary><p>These are illustrative prepared-food references, not nutrients measured from an image. The scenario range combines ±20% portion variation with ±15% recipe variation. It is not a validated confidence interval; the real value may fall outside it. Enter a measured portion or use an ingredient recipe for more useful tracking.</p></details><label class="meal-confirm"><input name="confirmed" type="checkbox" required>I reviewed the dishes and portions and understand this is an approximate estimate.</label><div class="action-row"><button type="submit" class="btn">${icon('check')}Log approximate meal</button></div><p id="meal-error" class="error" role="alert"></p></form></section>`;}
function renderAdd(){return `${heading('SMALL STEPS, A CLEARER PICTURE','Every meal has a place.','Choose a source, review your portion, and add it to your day.')}<div class="tabs" role="tablist" aria-label="Food source">${[['photo','camera','Snap a meal'],['home','home','Home cooked'],['orders','bag','Zomato orders'],['label','scan','Scan a label']].map(([tab,i,n])=>`<button class="tab ${activeTab===tab?'active':''}" role="tab" aria-selected="${activeTab===tab}" data-action="switch-tab" data-tab="${tab}">${icon(i)}${n}</button>`).join('')}</div><div class="layout"><div>${activeTab==='photo'?mealForm():activeTab==='home'?homeForm():activeTab==='orders'?ordersForm():labelForm()}</div><aside><section class="inspiration" style="margin-top:0"><div class="eyebrow">A LITTLE CONTEXT</div><h3>Portions make<br>the difference.</h3><p>Two plates of the same dish can have different amounts of oil, ingredients and food. Confirming your portion makes your estimate more useful.</p><a href="#about" class="text-btn">How this demo works ${icon('arrow')}</a></section><p class="quiet-note">All logs are added to today. Meal photo estimates use illustrative references after you review the dishes. Community sharing is local to this browser.</p></aside></div>`;}
function recipeCard(r){const m=recipeMacros(r.rows,r.yieldG,r.portionG).portion;return `<article class="card recipe-card"><div class="recipe-art ${escape(r.color||'yellow')}">${plate()}</div><div class="recipe-card-body"><div class="recipe-author">${escape(r.author)} · ${escape(r.region)}</div><h3>${escape(r.name)}</h3><p>${escape(r.description||'A recipe shared with ingredient quantities and portion information.')}</p><div class="recipe-macros"><span><b>${fmt(m.kcal)}</b>kcal</span><span><b>${fmt(m.protein,1)} g</b>protein</span><span><b>${r.portionG} g</b>portion</span></div><div class="badge-line"><span class="pill">RECIPE ESTIMATE</span>${r.author==='You'?'<span class="pill orange">YOUR LOCAL POST</span>':'<span class="pill orange">SAMPLE RECIPE</span>'}</div><div class="recipe-card-actions"><button class="text-btn" data-action="recipe-detail" data-id="${escape(r.id)}">View recipe</button><button class="save-btn ${r.saved?'saved':''}" data-action="save-recipe" data-id="${escape(r.id)}" aria-pressed="${r.saved}">${r.saved?'Saved ✓':'Save'}</button><button class="btn small" data-action="log-recipe" data-id="${escape(r.id)}">+ Log</button></div></div></article>`;}
function renderCommunity(){let recipes=state.recipes;if(communityFilter==='saved')recipes=recipes.filter(r=>r.saved);if(communityFilter==='protein')recipes=recipes.filter(r=>recipeMacros(r.rows,r.yieldG,r.portionG).portion.protein>=20);return `${heading('FROM ONE KITCHEN TO ANOTHER','Good food travels.','Recipes you can understand, make your own, and add to your diary.')}<section class="community-banner"><div><h3>Share the recipe behind your plate.</h3><p>Ingredients, quantities and portions make a recipe useful to someone else.</p></div><button class="btn" data-action="add-tab" data-tab="home">${icon('plus')}Share a recipe</button></section><div class="community-toolbar"><div class="filters">${[['all','All recipes'],['protein','20g+ protein'],['saved','Saved']].map(([id,label])=>`<button class="filter ${id===communityFilter?'active':''}" aria-pressed="${id===communityFilter}" data-action="filter" data-filter="${id}">${label}</button>`).join('')}</div><span class="small-copy">${recipes.length} recipes · local demo feed</span></div><div class="community-grid">${recipes.length?recipes.map(recipeCard).join(''):'<div class="card empty">No recipes here yet. Save a recipe or share your own.</div>'}</div><p class="notice">All macro values are recipe estimates using illustrative ingredient references. Posts need ingredient and portion review before becoming trusted reference data. Saving a post does not verify its nutrition.</p>`;}
function renderAbout(){return `${heading('THE IDEA BEHIND THALI','Built around the way we eat.','An independent concept for Eternal Hackathon Showcase 2026.')}<div class="about-grid"><section class="card"><h3>The problem we’re exploring</h3><p>Home cooking, restaurant food and packaged snacks need different logging steps. Thali brings them into a shared diary and makes recipes reusable. We want to test whether this reduces logging effort and supports more informed choices.</p></section><section class="card"><h3>Where Eternal fits</h3><p>Zomato already offers nutrition discovery through Healthy Mode. Thali proposes connecting that context with the rest of a user’s day. Approved order access and optional Blinkit ingredient baskets are future opportunities, subject to data access and partnership.</p></section><section class="card"><h3>What works in this demo</h3><ul><li>On-device AI meal photo suggestions with reviewed portion ranges</li><li>Ingredient and portion calculations</li><li>Sample order logging and daily macro totals</li><li>Browser photo OCR, text parsing and manual review</li><li>Local recipe sharing, saving, logging and export</li></ul></section><section class="card"><h3>Data you can understand</h3><p>Recipes, prepared-food references and restaurant values are illustrative. Labels and AI dish suggestions require your review. Photo ranges are scenario bounds, not validated confidence intervals. Cooked yield is used to scale recipe portions; cooking retention is not modelled. No Zomato or Blinkit account is connected. The feed is a local prototype, with no shared server or clinical recommendations.</p></section><section class="card"><h3>Your browser, your diary</h3><p>Entries, recipes and example goals stay in this browser’s storage. Photos are not uploaded or saved. AI model files download from Hugging Face and are cached by the browser. You can export your diary, remove individual entries, clear your data or restore the sample day. Only share non-sensitive examples during a presentation.</p><div class="demo-actions"><button class="btn outline small" data-action="export">Export diary</button><button class="btn outline small" data-action="reset">Restore sample data</button><button class="btn outline small" data-action="clear">Clear my data</button></div>${!storageAvailable?'<p class="error">Persistent storage is unavailable in this browser.</p>':''}</section><section class="card"><h3>References and next steps</h3><p><a href="https://www.zomato.com/blog/zomato-healthy-mode-explained-scores-nutrition-info-smart-filters/" target="_blank" rel="noopener">Zomato Healthy Mode</a><br><a href="https://www.eternal.com/" target="_blank" rel="noopener">Eternal’s businesses</a><br><a href="https://nin.res.in/ebooks/IFCT2017_16122024.pdf" target="_blank" rel="noopener">ICMR NIN food composition data scope</a></p><p style="margin-top:10px">Next: evaluate dish recognition and portion errors on Indian meals, user interviews, a small pilot, reviewed nutrition references and approved integrations.</p></section></div>`;}
function render(){const route=location.hash.slice(1)||'today';const view=['today','add','community','about'].includes(route)?route:'today';$$('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#view').innerHTML=({today:renderToday,add:renderAdd,community:renderCommunity,about:renderAbout})[view]();if(view==='add'&&activeTab==='home')updateRecipe();if(view==='add'&&activeTab==='label')updateLabel();if(view==='add'&&activeTab==='photo'){showMealMatches();updateMealEstimate();}}
function readMealRows(){if($('#meal-components'))mealRows=$$('.meal-component').map(el=>({id:$('.meal-dish',el).value,grams:Number($('.meal-grams',el).value)}));return mealRows;}
function updateMealEstimate(){if(!$('#meal-form'))return;const draft=new FormData($('#meal-form'));mealDraft={name:String(draft.get('name')),meal:draft.get('meal'),oil:draft.get('oil')};try{const result=estimatePhotoMeal(readMealRows(),$('#meal-form [name="oil"]').value);$('#meal-estimate').innerHTML='<div class="result-top">APPROXIMATE SCENARIO RANGE</div><div class="macro-stats">'+KEYS.map(k=>`<div><b>${fmt(result.low[k],k==='kcal'?0:1)}–${fmt(result.high[k],k==='kcal'?0:1)}${k==='kcal'?'':'g'}</b><small>${k==='kcal'?'Calories · kcal':k[0].toUpperCase()+k.slice(1)}</small></div>`).join('')+'</div><p class="field-hint">Diary reference estimate: '+fmt(result.midpoint.kcal)+' kcal. The range will be saved with your log.</p>';}catch(err){$('#meal-estimate').innerHTML='<p class="small-copy">'+escape(err.message)+'</p>';}}
function redrawMealRows(){if(!$('#meal-components'))return;$('#meal-components').innerHTML=mealRows.map(mealRowHTML).join('');$('#meal-form [name="confirmed"]').checked=false;updateMealEstimate();}
function showMealMatches(){if(!$('#meal-matches'))return;$('#meal-matches').innerHTML=mealResults?`<div class="meal-matches"><div class="eyebrow">TOP VISUAL MATCHES · REVIEW REQUIRED</div><p>${mealResults.needsManual?'The model did not choose a supported single dish. Select the dishes manually.':'These are alternative matches, not a list of everything on the plate. Confirm the suggested dish and add any sides.'}</p><div>${mealResults.matches.map(m=>`<button type="button" class="match-chip" data-action="pick-meal-dish" data-id="${m.dish.id}">+ ${escape(m.dish.name)}</button>`).join('')}</div><small>A match can be wrong, including for foods outside the 20 supported types.</small></div>`:'';}
function cancelMealScan(){mealRequest++;if(mealWorker)mealWorker.terminate();mealWorker=null;mealBusy=false;mealStatus='Scan stopped. You can select the dishes manually.';}
async function suggestMeal(){
 if(!mealPhotoURL){toast('Choose a meal photo or try the sample first.');return;}
 if(mealBusy)return;
 const id=++mealRequest,source=mealPhotoURL;mealBusy=true;mealStatus='Preparing your photo for on-device analysis…';render();
 try{
  const blob=await fetch(source).then(r=>r.blob()),bitmap=await createImageBitmap(blob),canvas=document.createElement('canvas'),factor=Math.min(1,1024/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*factor);canvas.height=Math.round(bitmap.height*factor);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();
  if(id!==mealRequest)return;
  if(!mealWorker){mealWorker=new Worker(new URL('./meal-worker.js',import.meta.url),{type:'module'});mealWorker.onerror=()=>{cancelMealScan();mealStatus='The AI reader could not load. Select dishes manually below, or retry on a compatible browser.';if($('#meal-ai-status'))render();};}
  mealWorker.onmessage=({data})=>{if(data.id!==mealRequest)return;if(data.type==='progress'){mealStatus=data.message;if($('#meal-ai-status'))$('#meal-ai-status').textContent=mealStatus;return;}mealBusy=false;if(data.type==='error'){mealStatus=data.message;}else{try{mealResults=rankMealMatches(data.results);mealUsedAI=true;mealStatus='AI analysis finished. Review the food matches and portions before logging.';}catch(err){mealStatus=err.message;}}if($('#meal-ai-status'))render();};
  mealWorker.postMessage({id,image:canvas.toDataURL('image/jpeg',0.9),labels:[...MEAL_DISHES.map(d=>d.label),...OTHER_LABELS]});
 }catch(err){mealBusy=false;mealStatus='Could not read this photo. Try a different JPG or PNG, or select dishes manually.';if($('#meal-ai-status'))render();}
}
function readRecipe(){const form=$('#recipe-form'),data=new FormData(form);const rows=$$('.ingredient-row',form).map(row=>({id:$('.ingredient-id',row).value,grams:Number($('.ingredient-grams',row).value)}));const result=recipeMacros(rows,data.get('yield'),data.get('portion'));const name=String(data.get('name')).trim();if(!name)throw new Error('Give your recipe a name.');return {name,meal:data.get('meal'),description:String(data.get('description')).trim(),rows,...result};}
function updateRecipe(){try{const r=readRecipe();$('#recipe-result').innerHTML='<div class="result-top">YOUR PORTION · '+fmt(r.portionG)+' G · ESTIMATE</div>'+macrosHTML(r.portion);$('#recipe-error').textContent='';}catch(e){$('#recipe-result').innerHTML='<p class="small-copy">'+escape(e.message)+'</p>';}}
function readLabel(){const form=$('#label-form'),data=new FormData(form);if(!data.get('basis'))throw new Error('Confirm whether the label values are per 100 g or per serving.');const values=Object.fromEntries(KEYS.map(k=>[k,data.get(k)]));return {data,macros:labelMacros(values,data.get('basis'),data.get('basisGrams'),data.get('consumed'))};}
function updateLabel(){if(!$('#label-form'))return;$('#label-serving').disabled=$('#label-basis').value==='100g';try{const {data,macros}=readLabel();$('#label-result').innerHTML='<div class="result-top">YOUR PORTION · '+escape(data.get('consumed'))+' G</div>'+macrosHTML(macros);}catch(e){$('#label-result').innerHTML='<p class="small-copy">'+escape(e.message)+'</p>';}}
function addEntry(entry){state.entries.push({id:uid(),day:localDay(),...entry});persist();toast('Added to today’s diary.');}
function addTab(tab){activeTab=tab;if(location.hash==='#add')render();else location.hash='add';}
function showModal(content){$('#modal-content').innerHTML=content;$('#modal').showModal();}
function closeModal(){ $('#modal').close(); }
function showGoals(){showModal(`<div class="modal-top"><h2>Your daily goals</h2><button class="close-modal" data-action="close" aria-label="Close">×</button></div><p class="goal-note">These are example preferences, not a nutrition prescription. Enter goals you have chosen for yourself.</p><form id="goals-form"><div class="review-grid">${KEYS.map(k=>`<label class="field"><span>${k==='kcal'?'Calories · kcal':k[0].toUpperCase()+k.slice(1)+' · g'}</span><input name="${k}" type="number" min="1" max="${k==='kcal'?'20000':'3000'}" step="any" value="${state.goals[k]}" required></label>`).join('')}</div><button class="btn full" type="submit">Save goals</button></form>`);}
function recipeDetail(id){const r=state.recipes.find(x=>x.id===id);if(!r)return;const m=recipeMacros(r.rows,r.yieldG,r.portionG).portion;showModal(`<div class="modal-top"><h2>${escape(r.name)}</h2><button class="close-modal" data-action="close" aria-label="Close">×</button></div><p class="small-copy">By ${escape(r.author)} · recipe estimate · ${r.portionG} g portion</p><div class="recipe-results">${macrosHTML(m)}</div><h3>Ingredients</h3><ul class="recipe-detail-list">${r.rows.map(row=>`<li>${escape(INGREDIENTS.find(i=>i.id===row.id)?.name)} · ${row.grams} g raw</li>`).join('')}</ul><p class="small-copy">Final cooked batch: ${r.yieldG} g. Portion: ${r.portionG} g.</p><p class="notice">${escape(r.description||'No preparation note added.')}</p><p class="notice">Illustrative ingredient references. Adjust ingredient quantities and yield for your kitchen.</p><button class="btn full" data-action="log-recipe" data-id="${escape(id)}">Log one portion today</button>`);}
function applyLabelText(text){const result=parseLabel(text);for(const k of KEYS)$('#label-'+k).value=result[k];$('#label-basis').value=result.basis;$('#label-serving').value=result.basisGrams;$('#label-form [name="confirmed"]').checked=false;updateLabel();$('#scan-status').textContent='Candidate values extracted. Review the fields and label basis below.';}
async function scanPhoto(){
 if(!photoURL){toast('Choose a label photo first, or try the sample.');return;}
 const button=$('[data-action="scan"]'),status=$('#scan-status'),source=photoURL;button.disabled=true;status.textContent='Loading the OCR reader. First use can take a moment…';
 try{
  if(!window.Tesseract){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';script.onload=resolve;script.onerror=()=>reject(new Error('OCR download failed. Paste the text or enter the values manually.'));document.head.append(script);});}
  if(!scanWorker)scanWorker=await window.Tesseract.createWorker('eng',1,{logger:m=>{if(status.isConnected)status.textContent=m.status.replace(/\b\w/g,c=>c.toUpperCase())+(m.progress?' · '+Math.round(m.progress*100)+'%':'');}});
  const {data}=await scanWorker.recognize(source);
  if($('#label-text')&&status.isConnected&&source===photoURL){$('#label-text').value=data.text;applyLabelText(data.text);}
 }catch(e){if(status.isConnected)status.textContent=e.message||'Could not read this image. Enter the values manually.';}
 finally{if(button.isConnected)button.disabled=false;}
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
 if(action==='add-tab')addTab(b.dataset.tab);
 if(action==='switch-tab'){activeTab=b.dataset.tab;render();}
 if(action==='goals')showGoals();
 if(action==='close')closeModal();
 if(action==='delete-entry'){state.entries=state.entries.filter(x=>x.id!==b.dataset.id);persist();render();toast('Entry removed.');}
 if(action==='add-ingredient'){$('#ingredients').insertAdjacentHTML('beforeend',ingredientRow({id:'oil',grams:5},$$('.ingredient-row').length));updateRecipe();}
 if(action==='remove-ingredient'){b.closest('.ingredient-row').remove();updateRecipe();}
 if(action==='log-order'){try{const order=SAMPLE_ORDERS.find(o=>o.id===b.dataset.id);const input=$('#portions-'+order.id);if(!input.reportValidity())return;const portions=positive(input.value,'Portions');addEntry({name:order.name,meal:order.meal,source:'order',provenance:'Fictional sample order · illustrative values',portion:`${portions} portion${portions===1?'':'s'}`,macros:scaleMacros(order.macros,portions)});}catch(err){toast(err.message);}}
 if(action==='publish-recipe'){try{const r=readRecipe();state.recipes.unshift({id:uid(),name:r.name,author:'You',region:'Your kitchen',description:r.description||'A recipe shared with measured ingredients and a defined cooked yield.',rows:r.rows,yieldG:r.yieldG,portionG:r.portionG,color:'green',saved:false});communityFilter='all';persist();location.hash='community';toast('Recipe shared in your local demo feed.');}catch(err){$('#recipe-error').textContent=err.message;}}
 if(action==='filter'){communityFilter=b.dataset.filter;render();}
 if(action==='save-recipe'){const r=state.recipes.find(r=>r.id===b.dataset.id);r.saved=!r.saved;persist();render();}
 if(action==='recipe-detail')recipeDetail(b.dataset.id);
 if(action==='log-recipe'){const r=state.recipes.find(r=>r.id===b.dataset.id);if(r)addEntry({name:r.name,meal:'Snack',source:'home',provenance:'Community recipe estimate · illustrative references',portion:`${r.portionG} g`,macros:recipeMacros(r.rows,r.yieldG,r.portionG).portion});if($('#modal').open)closeModal();}
 if(action==='parse-label')applyLabelText($('#label-text').value);
 if(action==='sample-label'){$('#label-text').value='Nutrition information\nPer 100 g\nEnergy 380 kcal\nProtein 20 g\nCarbohydrate 60 g\nTotal fat 6 g';$('#label-form [name="name"]').value='Roasted chana · sample';$('#label-form [name="meal"]').value='Snack';applyLabelText($('#label-text').value);$('#label-preview').src='./sample-label.png';$('#scan-status').textContent='Illustrative sample loaded. Review the values; try Read photo to run OCR on it.';photoURL=new URL('./sample-label.png',location.href).href;}
 if(action==='scan')scanPhoto();
 if(action==='suggest-meal')suggestMeal();
 if(action==='cancel-meal'){cancelMealScan();render();}
 if(action==='sample-meal'){if(mealPhotoURL.startsWith('blob:'))URL.revokeObjectURL(mealPhotoURL);mealPhotoURL=new URL('./sample-meal.jpg',location.href).href;mealRows=[];mealResults=null;mealUsedAI=false;mealDraft={name:'My meal photo',meal:'Lunch',oil:0};mealStatus='Sample meal photo loaded. Run AI analysis or select the dishes manually.';render();}
 if(action==='add-meal-component'){readMealRows();const d=MEAL_DISHES[0];mealRows.push({id:d.id,grams:d.grams});redrawMealRows();}
 if(action==='remove-meal-component'){readMealRows();mealRows.splice(Number(b.dataset.index),1);redrawMealRows();}
 if(action==='pick-meal-dish'){readMealRows();const d=MEAL_DISHES.find(d=>d.id===b.dataset.id);if(d){if(mealRows.some(r=>r.id===d.id)){toast('This dish is already added. Adjust its weight below.');}else{mealRows.push({id:d.id,grams:d.grams});redrawMealRows();}}}
 if(action==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='thali-diary-'+localDay()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Diary exported.');}
 if(action==='reset'||action==='clear'){showModal(`<div class="modal-top"><h2>${action==='clear'?'Clear your demo data?':'Restore the sample day?'}</h2><button class="close-modal" data-action="close" aria-label="Close">×</button></div><p class="notice">This replaces the diary, saved recipes and goals stored in this browser. Export your diary first if you want to keep a copy.</p><div class="action-row"><button class="btn danger" data-action="confirm-${action}">${action==='clear'?'Clear data':'Restore samples'}</button><button class="btn outline" data-action="close">Cancel</button></div>`);}
 if(action==='confirm-reset'||action==='confirm-clear'){state=fresh();if(action==='confirm-clear'){state.entries=[];state.recipes=[];}selectedDay=localDay();persist();closeModal();render();toast(action==='confirm-clear'?'Local diary and recipes cleared.':'Sample data restored.');}
});
document.addEventListener('submit',e=>{
 if(e.target.id==='recipe-form'){e.preventDefault();try{const r=readRecipe();addEntry({name:r.name,meal:r.meal,source:'home',provenance:'Recipe estimate · illustrative references',portion:`${r.portionG} g`,macros:r.portion});selectedDay=localDay();location.hash='today';}catch(err){$('#recipe-error').textContent=err.message;}}
 if(e.target.id==='label-form'){e.preventDefault();try{const {data,macros}=readLabel();if(!data.get('confirmed'))throw new Error('Please review and confirm the values before logging.');addEntry({name:String(data.get('name')).trim(),meal:data.get('meal'),source:'snack',provenance:'User reviewed label · entered values',portion:`${data.get('consumed')} g`,macros});selectedDay=localDay();location.hash='today';}catch(err){$('#label-error').textContent=err.message;}}
 if(e.target.id==='goals-form'){e.preventDefault();const data=new FormData(e.target);state.goals=Object.fromEntries(KEYS.map(k=>[k,positive(data.get(k),'Goal')]));persist();closeModal();render();toast('Daily goals updated.');}
 if(e.target.id==='meal-form'){e.preventDefault();try{const data=new FormData(e.target);if(!data.get('confirmed'))throw new Error('Review and confirm the dishes and portions before logging.');const rows=readMealRows(),estimate=estimatePhotoMeal(rows,data.get('oil'));addEntry({name:String(data.get('name')).trim()||'My meal photo',meal:data.get('meal'),source:'photo',provenance:(mealUsedAI?'AI-assisted photo estimate':'Manually selected meal estimate')+' · user reviewed · illustrative references',portion:rows.map(r=>MEAL_DISHES.find(d=>d.id===r.id).name+' '+r.grams+' g').join(', '),macros:estimate.midpoint,macroRange:{low:estimate.low,high:estimate.high},components:rows.map(r=>({...r})),extraOilTsp:Number(data.get('oil'))});selectedDay=localDay();mealRows=[];mealResults=null;mealUsedAI=false;location.hash='today';}catch(err){$('#meal-error').textContent=err.message;}}
});
document.addEventListener('input',e=>{if(e.target.closest('#recipe-form'))updateRecipe();if(e.target.closest('#label-form')){if(e.target.name!=='confirmed')$('#label-form [name="confirmed"]').checked=false;updateLabel();}if(e.target.closest('#meal-form')){if(e.target.name!=='confirmed')$('#meal-form [name="confirmed"]').checked=false;updateMealEstimate();}});
document.addEventListener('change',e=>{
 if(e.target.classList.contains('meal-dish')){readMealRows();redrawMealRows();}
 if(e.target.id==='meal-photo-file'){
  const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Choose a JPG, PNG or WebP image under 10 MB.');e.target.value='';return;}
  if(mealBusy)cancelMealScan();else mealRequest++;
  if(mealPhotoURL.startsWith('blob:'))URL.revokeObjectURL(mealPhotoURL);mealPhotoURL=URL.createObjectURL(file);mealRows=[];mealResults=null;mealUsedAI=false;mealDraft={name:'My meal photo',meal:'Lunch',oil:0};mealStatus='Photo ready. Run AI analysis, then confirm each dish and portion.';render();
 }
 if(e.target.id==='diary-date'){if(e.target.value){selectedDay=e.target.value;render();}}
 if(e.target.id==='label-file'){
  const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type)){toast('Choose a JPG, PNG or WebP image under 10 MB.');e.target.value='';return;}
  if(photoURL.startsWith('blob:'))URL.revokeObjectURL(photoURL);photoURL=URL.createObjectURL(f);$('#label-preview').src=photoURL;$('#scan-status').textContent='Photo ready. Select Read photo, then review the extracted values.';
  for(const k of KEYS)$('#label-'+k).value='';$('#label-basis').value='';$('#label-form [name="confirmed"]').checked=false;updateLabel();
 }
});
$('#profile').addEventListener('click',showGoals);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
render();
